  let ev = vec3<f32>(a[0][0], a[1][1], a[2][2]);
  if (ev[order.y] < ev[order.x]) { order = vec3<u32>(order.y, order.x, order.z); }
  if (ev[order.z] < ev[order.y]) { order = vec3<u32>(order.x, order.z, order.y); }
  if (ev[order.y] < ev[order.x]) { order = vec3<u32>(order.y, order.x, order.z); }
